SELECT COUNT(DISTINCT CONCAT(i.warehouse_id, '-', i.sku_id))
FROM inventory i
JOIN sku s ON i.sku_id = s.id
WHERE 1 = 1

    AND i.warehouse_id = #{warehouseId}


    AND s.sku_code = #{skuCode}

SELECT i.warehouse_id AS warehouseId, w.warehouse_name AS warehouseName, i.sku_id AS skuId, s.sku_code AS skuCode, s.sku_name AS skuName, SUM(i.quantity) AS totalQuantity FROM inventory i JOIN sku s ON i.sku_id = s.id JOIN warehouse w ON i.warehouse_id = w.id WHERE 1 = 1
AND i.warehouse_id = #{warehouseId}
AND s.sku_code = #{skuCode}
GROUP BY i.warehouse_id, w.warehouse_name, i.sku_id, s.sku_code, s.sku_name ORDER BY i.warehouse_id, i.sku_id LIMIT #{offset}, #{size}
